CREATE TABLE `danhgia` (
  `danhgia_id` int NOT NULL AUTO_INCREMENT,
  `danhgia_khoahoc_id` int NOT NULL,
  `danhgia_hocvien_id` int NOT NULL,
  `danhgia_sao` int NOT NULL,
  `danhgia_noidung` text,
  `danhgia_ngay` datetime DEFAULT CURRENT_TIMESTAMP,
  `danhgia_trangthai` enum('Hiển thị','Ẩn') NOT NULL DEFAULT 'Hiển thị',
  PRIMARY KEY (`danhgia_id`),
  KEY `danhgia_khoahoc_id` (`danhgia_khoahoc_id`),
  KEY `danhgia_hocvien_id` (`danhgia_hocvien_id`),
  CONSTRAINT `danhgia_ibfk_1` FOREIGN KEY (`danhgia_khoahoc_id`) REFERENCES `khoahoc` (`khoahoc_id`) ON DELETE CASCADE,
  CONSTRAINT `danhgia_ibfk_2` FOREIGN KEY (`danhgia_hocvien_id`) REFERENCES `nguoidung` (`nguoidung_id`),
  CONSTRAINT `danhgia_chk_1` CHECK ((`danhgia_sao` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
