LOCK TABLES `danhgia` WRITE;
/*!40000 ALTER TABLE `danhgia` DISABLE KEYS */;
INSERT INTO `danhgia` VALUES (1,138,272,3,'Tôi khi đến. Tại là nhiều từ. Tôi có với nhưng.\nTrong khi này để với như. Với nhưng với nơi với nào nhiều. Và vài đã này cho.\nChỉ giữa mà thế. Người này cũng của theo hơn tại.','2024-07-18 03:21:20','Ẩn'),(2,140,277,2,'Chỉ sẽ lớn dưới vẫn vì vài mà. Về có được nhưng. Làm nơi thì nếu đó như vậy.\nTừng tại nhiều chưa từ chỉ người.\nĐể nơi bạn đó.\nVài vì tại vậy. Người cho cái thì sau từ. Đó thay vài cách nhiều thế.','2024-01-12 18:52:59','Ẩn'),(3,115,72,1,'Với của nhiều nếu có. Có rất để như tự sau.\nNgười thay để tại của vài điều.\nSau mỗi các có được từng. Từng điều nhiều sau như được.','2024-01-22 04:30:25','Ẩn'),(4,93,107,2,'Cái cũng thì vài mà đang này dưới. Cách cũng nhiều bạn bạn. Đi của đúng mỗi số bạn hơn. Gần rất để từ rất các rất giống.\nCho các theo thay thay có và. Không lớn cái có như.','2025-09-08 08:40:36','Hiển thị'),(5,178,141,5,'Mỗi nhưng mà với nhiều khiến tại. Khiến giữa sau. Cũng vài cách như. Người đến đi hơn từ.\nĐể rất đang lớn đến. Đến như từ không đang để giống cũng. Tự cũng như của vì trong trong.','2025-04-28 03:22:45','Ẩn'),(6,210,67,4,'Hơn dưới nhưng với về như tôi. Vì như vậy vài có. Nhiều của của bạn rất.\nDưới của tôi có giữa tự bạn giống. Khi không để giữa nào thì chỉ. Trong có này tại từ người khi.','2025-02-28 15:39:48','Hiển thị'),(7,67,216,4,'Giữa như đó của. Như thay hoặc từ đi đi từ.\nĐược với để giữa khi trong. Rất nơi không khiến nào từng có đã.\nNhư không được. Trong đó như chưa. Hơn thì gần vẫn tự số.','2025-09-25 18:57:27','Hiển thị'),(8,281,147,2,'Hơn đang đó một. Như sẽ về.\nVới gần hơn theo. Của khi của gần theo như. Trong làm với tôi được.\nCách lớn rất như cũng. Để giữa cũng thì của.\nCác thì hơn tại. Khi cũng từ.','2024-01-05 14:40:54','Hiển thị'),(9,285,72,3,'Từ lớn tôi hơn như. Tại của và là đúng thay sau hoặc. Với mà tôi sau.\nNhư tôi của đang đang. Và dưới về giống đó nơi.\nKhiến vì của chỉ. Được thì bên hoặc thì. Vì như đi bên bạn thì.','2025-03-22 02:20:27','Ẩn'),(10,176,159,2,'Không đúng vậy không cách dưới. Nhiều mà theo đúng tại từng giống.\nSố chỉ mà như vẫn. Để giống một vài rất để. Nào thế với để bên cách.\nTôi này hơn thay hơn vài. Đó mà vẫn thì tại cũng.','2024-09-08 18:46:45','Hiển thị'),(11,295,34,2,'Thay theo trong dưới mỗi mỗi vậy khi. Của là về hơn mỗi tôi các.\nCó nào như của các cho trong hoặc. Với có tại số nhiều thì. Các đã được.\nMỗi từ nhiều vài. Đến cách hơn nào và giữa vài vì.','2025-09-30 23:42:00','Ẩn'),(12,244,158,5,'Sẽ để đang vài cũng từng. Điều tại với người tại của chỉ hơn.\nHơn thì đến và từ tại. Các không thì của từng.\nNày đi làm.\nGiống đúng tự về điều bạn.\nMà theo tự của đang nơi. Bạn các chưa trong.','2025-01-04 18:24:00','Ẩn'),(13,107,295,4,'Hơn một của và của để. Dưới vài nơi như.\nMỗi về thì mỗi điều của cũng bạn. Mà đi là cách. Trong đó dưới giống.\nCác khiến trong chưa hơn được về. Như bạn trong rất của.','2025-07-29 12:43:31','Ẩn'),(14,18,34,3,'Chỉ của tôi để rất với đó. Tôi chưa một hơn có cũng. Trong tự theo tự số.\nVà lớn dưới. Trong với tôi tại nào.\nVới từ của thay nơi mỗi nơi của. Gần được khi. Mà theo vì cũng cho trong chưa.','2025-04-03 10:20:32','Ẩn'),(15,189,166,2,'Của vì lớn tại. Bạn mỗi của thì cách các.\nNhư như được đến tôi số hơn sau. Đến khiến điều vậy chỉ mỗi. Làm là thì đang tôi có.','2025-02-24 23:05:57','Ẩn'),(16,282,229,2,'Có nào với hơn tự để và. Không cũng được lớn. Như số cái và như chưa vậy mỗi.\nBạn điều không mà như vẫn.\nRất không của một làm đúng giữa. Vẫn số dưới vậy. Nhiều dưới mà khiến cũng từng vẫn.','2025-03-23 19:23:32','Ẩn'),(17,39,16,1,'Bên bên được nào để từng bạn. Như không khiến tôi thì như mà. Như này để có điều.\nKhiến để có bên. Giống thì như tôi mà rất đang. Trong đến với bạn từng hơn.','2024-02-15 17:34:27','Hiển thị'),(18,69,229,2,'Vài thay cách. Như số vì như này thì đúng.\nCũng bên tại từ để vậy này sau. Là không bạn như khiến nếu vậy.\nCủa từ đang như chưa cho vài. Đến theo có vậy như có. Tại đã là thay khiến đi.','2024-08-16 23:21:47','Ẩn'),(19,94,239,3,'Điều từ tự cũng điều. Đã đó mà như để.\nĐó các một hơn điều. Với tôi từ vì hơn sau đó nếu.\nNếu cũng tự nhiều mỗi vài. Tại vẫn vì để để. Thay chỉ thì từ có.','2024-06-26 03:27:05','Hiển thị'),(20,293,297,4,'Cách một hơn cách. Tự thì với hoặc.\nCủa của nơi thay. Cũng lớn đến giữa nhiều. Người có bạn của mỗi.\nNơi người đến tại. Khiến hơn từ nếu. Vài thì đang sẽ khi như với. Giữa có của số hơn như.','2024-05-04 15:00:30','Ẩn'),(21,147,34,4,'Sau như nếu của nhưng. Số thế tự hơn đó. Là về mà.\nChưa nếu và cũng rất một. Chỉ đó đúng nơi dưới. Chỉ lớn giống sẽ.\nCũng với như cũng đúng lớn với.\nDưới số có. Như với nào.\nĐiều có như nơi của.','2024-08-09 07:42:15','Hiển thị'),(22,178,166,4,'Đến hơn cho đã chưa có khi có. Thay mà khi theo về đó như. Cũng tại hoặc trong.\nNhư như thì của trong số.\nCủa là là giống có. Như không với đó.\nTheo giữa để từ thay bên thì. Tại để nào mỗi.','2025-03-01 17:48:14','Hiển thị'),(23,226,245,1,'Vẫn chỉ từ với để và có. Nhiều đang từ để.\nNhư như vẫn đúng có rất mỗi. Vài vẫn vẫn nhưng cũng cái bên. Vậy hơn trong điều mà.\nCho và trong làm. Điều lớn như số khiến đến các. Đi đã làm cho cách.','2024-02-26 16:51:13','Hiển thị'),(24,7,13,5,'Không chưa đúng. Của vậy theo tôi này.\nSố như trong như nhưng dưới mà. Vì của đã của. Giống này chưa hơn theo để từ chưa. Tôi với dưới.','2024-07-23 19:46:02','Hiển thị'),(25,229,256,2,'Trong điều có bạn cũng như vẫn. Bạn khiến với trong. Đó lớn tự chỉ số hơn tại mỗi.\nNhư tự làm có. Lớn lớn với với của cái.','2025-06-29 14:57:17','Hiển thị'),(26,82,89,5,'Giữa điều một trong đúng. Với số trong từng tôi như về các. Đúng sau sau của cho số lớn.\nVài về như để rất. Đúng vẫn người của tại này cũng. Thay như số điều nhưng.','2025-06-11 10:34:43','Hiển thị'),(27,234,54,4,'Đó và hơn để theo nhiều như. Các vài vậy thì để từ. Hơn từ cách vẫn nếu rất.\nĐược như thay sẽ thì đang. Trong từ khi gần mà vậy giống.\nSẽ đang để. Cách mỗi từng một của.','2024-02-07 16:05:15','Hiển thị'),(28,246,58,5,'Đang nhiều cho tại. Đúng này giống nhiều bạn thì gần. Này đang của trong với.\nChưa thì tại đi vậy như gần. Thay làm trong.\nĐang vài theo tại vài hơn số. Để của bạn hơn. Nhiều như vẫn với cách người.','2024-11-29 07:20:36','Ẩn'),(29,86,115,4,'Từng cái cũng. Nào hơn khi sau nếu giữa từng vậy.\nTrong dưới không từ chưa vì và.\nTại khi tự cái sẽ cách. Về số hơn không. Khiến điều gần để giữa hơn này.\nĐúng với và. Sau như mỗi. Các cũng đã khiến.','2024-01-10 08:05:13','Hiển thị'),(30,300,209,5,'Cũng bạn có thay hơn như để vẫn. Hơn cũng nhiều với đó cũng có. Rất với như được hoặc như với.\nĐến về lớn cũng. Có giống vậy đúng giống với các. Lớn bạn giống có.','2024-10-29 11:54:26','Ẩn'),(31,178,183,5,'Của từng dưới chưa. Bên giống nếu hơn giống đi.\nNhư nếu của vậy. Từ một giống. Mỗi vài các của thì với một từng.\nVới mỗi sau giữa vẫn thì của. Nơi nhưng có là thế được. Như tôi nơi sẽ làm.','2024-09-18 09:22:13','Ẩn'),(32,161,233,2,'Thì nơi đến của rất. Tôi dưới chưa các. Lớn cách từng tự bên.\nRất nhưng số vậy tại và. Các đúng làm. Tại giữa như khiến nào cách.\nTôi tôi được đó bạn. Số sẽ như.','2024-01-10 19:24:49','Hiển thị'),(33,58,21,4,'Đúng cũng để này. Từ được đi làm thế mà.\nĐược hơn vẫn gần dưới. Từ từ hơn thì tôi của.\nCủa của của đang tự dưới tại. Trong khi trong vậy của hoặc.','2025-08-27 09:40:56','Ẩn'),(34,196,47,1,'Là tự một đi vì bạn. Thì của vì đi một.\nĐúng có như về cũng mỗi từ. Cái mà hoặc từ tại số đó như. Một chỉ hoặc nhưng cái lớn thì đã.\nBạn số mà của dưới. Điều mà điều về đó. Vẫn cho đó hơn sau.','2024-12-03 02:43:59','Ẩn'),(35,159,119,1,'Các tôi từng gần nhiều. Rất của được nơi theo và. Một như như các và giống đó. Bạn để như như vài.\nMột tôi vẫn hơn để mỗi là. Cũng khiến trong. Thay để trong.\nĐúng hơn không. Mà cũng mỗi này nơi vài.','2024-05-16 01:34:34','Ẩn'),(36,200,179,4,'Vẫn như một. Tôi trong nơi tại nơi giống.\nĐã của vì. Là về rất cũng.\nHoặc cách thay vì không vài của thay. Nơi cho thì với dưới nếu tại. Thế với rất của.\nChỉ là về để đến thay. Đi với bạn vậy.','2025-08-15 04:15:46','Ẩn'),(37,15,129,1,'Như của giữa lớn trong này tôi gần. Mà giống hơn với. Thì vậy như trong như mà tại.\nThay chỉ với rất vậy về mà. Lớn thay trong của như và.','2025-06-17 13:20:06','Hiển thị'),(38,91,173,5,'Để đang làm đúng vài tại từ. Có cái làm tôi mà. Này điều đi của thì sẽ.\nDưới sau của nếu đã nhiều. Số từng để như mà dưới đúng.','2025-03-07 00:30:27','Hiển thị'),(39,80,193,4,'Không đã có được đi đó. Vì trong khiến tự này mà. Để thay này này như của.\nCách của rất như nhiều mỗi. Thế cũng vì nhiều của trong sẽ các.\nTừng bên mỗi đang.\nCũng làm lớn có lớn được dưới giống.','2024-10-04 23:46:49','Hiển thị'),(40,238,161,1,'Trong và làm như. Đi hơn với như có giữa. Của để hoặc khiến để khiến. Thay thì vẫn nào.\nNhư cũng nào cũng như.\nCũng với thế tại có đang để. Chưa từng về của vẫn vì.\nVà hoặc vài giữa nào chỉ đó.','2025-06-01 05:15:45','Hiển thị'),(41,72,286,1,'Đúng mà như tại vậy sẽ làm. Vài này để vậy đó khiến.\nTừ từ nhưng tại mà sau không. Để nhiều tôi hơn. Đã khi bên với như để sẽ.','2025-01-04 05:12:25','Ẩn'),(42,40,139,3,'Trong này nào cũng. Gần nhiều từ vẫn cũng.\nChưa như hơn nơi đi trong. Cũng điều cách có của. Theo tại vậy trong của.\nKhông cái chỉ. Người rất giống vẫn cách. Cũng khiến để tự nơi.','2025-05-16 12:30:23','Ẩn'),(43,198,157,3,'Tại như để chưa làm. Hoặc không dưới của từ đến của.\nDưới chỉ vài mà vậy. Lớn để là.\nTôi đi với mỗi. Vài làm nhưng sau.\nĐược nếu trong cái tự. Nhưng với từ tại.','2025-07-15 15:39:45','Hiển thị'),(44,295,255,1,'Để có không nhiều dưới mỗi cái bạn. Để theo có với từng hơn chỉ mà.\nTại theo để hoặc mà. Tại bạn số và sau. Cũng là tôi theo.','2024-10-30 11:50:51','Ẩn'),(45,216,154,1,'Mỗi của dưới để mà tôi. Chưa vẫn như hơn vẫn có như.\nTừ và để đang không đến. Hoặc cho hoặc là thay cũng.\nCũng giữa vậy có từng và. Dưới và đó lớn nhưng đi.','2024-03-14 08:56:04','Ẩn'),(46,13,266,2,'Mỗi khiến khi nào về vì từ khi.\nĐể nơi giữa vẫn. Của này được người đến để.\nNhư hơn để giống mà. Rất với tự nhiều điều lớn.\nMỗi nếu chỉ cũng hơn cũng. Chưa số số gần với cho bên.','2025-05-16 00:12:29','Ẩn'),(47,78,272,3,'Không là vẫn. Vẫn tôi số được chưa là các. Từ hơn không với này có.\nĐó có các thay này thì hơn. Như vậy với được.\nSẽ đang thế mỗi cách sẽ điều để. Gần cách cũng hơn. Số thay nhưng trong đến mỗi.','2024-07-14 18:21:14','Hiển thị'),(48,21,145,4,'Cái tại đang đã giống nhưng đó. Người chỉ vài nào cho để mà theo. Để mỗi cách thì nơi làm.\nTừ từ tại. Của dưới tại này sau.\nĐược nào các tại. Điều cái để mỗi tôi tự. Cách thay giống khi mỗi.','2024-06-21 12:18:48','Hiển thị'),(49,137,209,3,'Chưa rất điều khi nơi đi. Sau các và hơn cho.\nLớn với với làm cũng với đang. Khi gần bên đi. Khi sẽ như thì giữa tôi đến.\nMà vẫn gần vì thay tự dưới. Được bên đang là đúng như của.','2025-08-09 08:58:37','Hiển thị'),(50,14,170,2,'Có theo này. Tôi cũng cho từ sau. Điều bên người và để để làm.\nTôi người hơn cái đi. Không đúng sau có tại cách. Nhưng khi khi.','2024-12-21 14:06:58','Hiển thị'),(51,198,228,3,'Tôi mà rất vì sau để. Có mà thì mỗi. Để trong đã và với số.\nVậy thế vài thì. Của chưa của nhưng dưới.\nĐúng từ đến như được với. Trong như trong nếu cũng giữa.\nKhiến trong lớn để hơn đó người mà.','2024-05-01 12:30:35','Hiển thị'),(52,262,92,3,'Tại làm chỉ số từ. Để bên tự cũng về vẫn của.\nĐang nhiều từng cho. Trong để trong nơi. Đúng cái bên một với về có.\nSố có lớn. Cho nhiều một mà sau sau.','2025-06-05 00:18:32','Hiển thị'),(53,89,74,2,'Cũng tôi hơn người cũng. Người sau để giống như. Cho vậy bên vài với nếu.\nNgười làm từ trong. Sau chỉ số bên thì sẽ.','2025-10-29 16:35:34','Ẩn'),(54,114,219,5,'Chỉ cái hoặc của. Như cái mỗi thì lớn không. Nhiều hơn cũng đó không bạn giữa. Nếu bạn bạn tại.\nTự để điều đến được của. Cái thì đi tôi vì. Đúng vậy không rất. Mà có theo như.','2024-12-12 02:19:40','Ẩn'),(55,222,153,5,'Làm có thì như hoặc từ cũng cái. Cũng nếu đó số.\nChưa của thì theo như như. Cho không vẫn điều từ. Của số vậy.\nSẽ là mỗi trong. Tại và sau số điều.','2024-07-16 09:11:51','Ẩn'),(56,263,136,5,'Sau như để nếu để nhiều tôi. Vẫn cách bạn đúng của nhưng.\nNhưng từ sau với vẫn nơi vài thì. Thế mỗi chỉ.\nCủa điều bạn dưới tự. Trong đúng mỗi đi.','2025-12-27 06:43:56','Ẩn'),(57,291,296,4,'Người sẽ nào như thế. Khiến hơn nhiều cũng không không. Mỗi sau như vì vậy vẫn từng. Cũng các sẽ trong để.\nSau sẽ cũng. Nơi đó đã của chỉ. Hoặc như nào.','2024-08-19 08:10:10','Ẩn'),(58,133,254,3,'Đi hoặc đúng hơn của cái. Về khi là như trong nơi từ hoặc. Chỉ cho đang cũng một cách.\nTrong đi như nơi. Với điều thay để theo không với. Cái từ tại và lớn với tôi nhưng.','2024-01-01 04:44:44','Ẩn'),(59,22,241,5,'Giống là thay các không người đến. Để các theo đã bạn.\nMỗi cách bạn một này. Nhưng cách từ. Thì sẽ nào gần bên như các. Tại từ của được người như rất dưới.','2024-12-11 17:00:58','Hiển thị'),(60,57,279,3,'Như từng cái của nếu không giống. Rất để nhiều người đúng cái.\nKhi điều trong một vì chưa thay. Hoặc giữa từng thế theo.\nHơn lớn như một. Để rất mà như vẫn vì. Để rất cũng. Thay vẫn nơi đang.','2025-05-18 02:46:17','Hiển thị'),(61,203,202,4,'Đến được gần đã vẫn bên từng. Đó vậy nơi đang dưới để đi của. Nào chỉ tôi này đó các.\nCủa lớn người như cũng đến. Một là nơi là thì của. Với của rất.\nMà nhưng một lớn mà.','2025-05-30 14:40:33','Hiển thị'),(62,37,217,5,'Đúng để trong với rất cũng đi điều. Của của vì.\nĐúng lớn làm không hoặc được. Khi làm nếu một như làm với khiến.\nVà là sẽ đã cách đi gần một. Tôi cách giữa của.','2024-02-04 09:18:22','Hiển thị'),(63,155,139,2,'Hơn như tự làm về. Của này thay được.\nVà đó nào.\nLàm của như rất. Của giữa hơn của làm tại. Để của mỗi.\nNày đúng đi bạn thế có từng tự. Số có thay vài chỉ hơn làm.','2025-11-06 19:08:59','Hiển thị'),(64,208,111,1,'Thay đến để thì là. Theo làm cho cũng. Cũng để cũng không làm để một. Như và tự tôi đúng chỉ.\nĐang bên đang khiến đúng. Để bạn đó một.\nCủa rất tôi. Để rất nơi cách điều cũng hơn.','2025-09-22 01:57:19','Hiển thị'),(65,300,298,5,'Đã để sẽ tại. Này trong như cái trong vì.\nĐó sẽ như một. Sẽ đang trong giữa đúng thì.\nTự vậy nhiều như tại cũng về khi. Điều đúng các với giữa từng đến này.','2024-01-24 00:41:26','Ẩn'),(66,284,183,4,'Các bên chưa. Đúng đã trong là với.\nRất đó khi tại. Trong của để thì. Bạn hơn một rất.\nNhư từ của sẽ theo. Bên có khiến đúng. Thế về được để sau.','2025-02-25 04:20:28','Hiển thị'),(67,194,123,5,'Từng dưới thế tại. Của chưa đã cũng. Với như giống với được.\nCủa vậy như trong có vẫn.','2024-06-03 05:42:10','Ẩn'),(68,248,265,5,'Hơn thì cũng cho. Nhiều đã mỗi. Vì thay cái giống vài về mà.\nCũng số không từ nào từ với. Gần mà có có hơn của.\nKhiến để tại sau đã cho. Như tự tôi chỉ hơn thay thay. Chưa với như cũng có.','2024-01-16 23:01:30','Ẩn'),(69,27,102,4,'Nơi cũng vậy hoặc có nhưng để. Giữa hoặc vài các tại. Từ như khiến từ với nào tôi.\nTự giống đó như chỉ. Thay được và cách. Mỗi này đang với giống.\nĐể giống hoặc dưới như. Sẽ để thay hơn nhiều đã làm.','2025-12-25 11:33:53','Hiển thị'),(70,218,179,4,'Được vẫn tại thay. Các được như rất có có cũng lớn. Tôi có thế.\nTừng tự bên vậy đã hơn. Cho các của được rất.\nTự nhưng khi của tại. Mỗi giữa từ khiến vài chưa cái.','2025-02-07 14:01:38','Ẩn'),(71,54,165,1,'Bạn này dưới cái cách. Giữa từ nào vài nhiều một. Đúng dưới người theo khiến.\nCủa một cũng cái rất cũng. Để đến thay này. Đi một vậy nếu tôi vài thì khiến.','2025-07-19 12:11:23','Hiển thị'),(72,16,200,2,'Để thay về tại như vài đó. Là theo là để một. Nhiều lớn vậy.\nCũng tại giữa nếu. Như tại với về để bên.\nVới về đó tôi. Đó được cái thế với từ. Dưới mà bạn dưới thế gần như hơn.','2025-12-16 14:55:26','Hiển thị'),(73,236,129,4,'Vài sẽ là. Sau đi để cái tại nhưng thì.\nMột vài để vì thì. Giữa vẫn tự gần đó nào. Lớn từ giống bạn tại từng.\nTôi tự để theo. Có này từng với như. Của chưa theo tại lớn.','2024-11-06 21:09:41','Ẩn'),(74,53,289,3,'Một số bạn. Mà tại tôi từng.\nThế gần có như. Hoặc sẽ đó sau. Làm điều từ với.\nChưa có như cũng một như sẽ cho. Khi hơn để. Nào như sẽ nơi hơn bạn tôi.','2025-05-19 15:06:21','Hiển thị'),(75,75,144,3,'Để các giống chỉ thế tôi. Có từ khi từ.\nNơi để làm nhiều cách thì. Được người của của như tự cũng. Với trong là chưa.\nNhiều sau đi cũng. Chưa nếu số cách lớn nào. Giống tại được nếu như để như.','2024-03-18 15:10:14','Ẩn'),(76,212,289,5,'Hơn như nhưng. Như hơn chỉ trong khiến đã vẫn.\nCủa đó bên nơi tại là khiến. Cho thế nơi để nếu để sau. Được cái đi như chưa chỉ khiến.\nSau có tại với. Để làm từng với nhiều.','2025-06-29 15:22:04','Ẩn'),(77,168,59,5,'Vì có được. Nhưng và cái mỗi.\nCủa của thì khiến có. Cũng vậy các đi cho và tại người. Với được sẽ chưa được. Nào cũng như giữa cũng đã.','2024-11-18 07:02:32','Ẩn'),(78,107,66,1,'Giống đi hoặc có. Như bạn cho. Vẫn từng có từ.\nTrong gần hơn một số người bạn về. Để sẽ hoặc tại bạn.\nKhi rất hơn thay bên vẫn. Vẫn người mỗi rất thì hoặc. Với cách từ có tôi để nhưng của.','2025-01-25 20:32:16','Hiển thị'),(79,134,27,1,'Hơn nhưng của không vậy tự tôi. Từ tại tại từ cái như cũng bạn. Của mà như khi của người tôi. Có là vài một cho điều.\nDưới của không hoặc mỗi đi đến. Như về sau với khiến.','2025-08-13 17:56:25','Ẩn'),(80,28,38,3,'Cũng số đến khiến hơn trong. Gần từ đó với hơn. Nhưng của dưới nhưng là sẽ hoặc.\nMột khi nơi này vì vậy sẽ được. Tại chỉ một khiến như lớn. Nào các với được đang cái bạn.','2024-06-30 07:13:40','Ẩn'),(81,232,228,1,'Là hơn được sẽ gần nhưng cũng chưa. Mỗi chỉ mỗi.\nCách có các trong một có nhiều. Cách nhiều sau chưa. Này tôi chưa tại.\nTại đi rất nơi tự. Bạn đã như về.','2024-04-10 03:58:57','Ẩn'),(82,245,100,4,'Gần nhiều bên với.\nNhiều từ và đã. Với sau số của. Theo như vài trong tôi cách.\nĐang vài như nhiều sau. Theo từ giống theo người. Đang khi đó thay này đó sẽ.','2024-04-19 15:41:24','Ẩn'),(83,232,269,2,'Của chưa cái vì. Như này vì theo đó thì được chưa.\nGiữa khi bạn vì cho. Không nơi đang với khiến bạn. Trong nhưng đang với khiến làm đến đến.\nMà sau với cách không. Cũng nhưng thay hoặc để trong.','2025-10-09 22:56:12','Ẩn'),(84,163,250,3,'Hơn gần tự số với chưa có. Đó các tại người. Dưới số số dưới của hoặc.\nĐược đã đi đã lớn hơn sau. Thì người cho. Số đúng cách đến.\nThay thì mỗi khi. Của hoặc để cũng.','2025-04-04 21:57:15','Ẩn'),(85,159,277,2,'Là cũng đó từng khiến của cũng. Tại số điều và giữa trong nếu người. Có nơi của khi lớn dưới chỉ.\nVài vẫn lớn vì đúng vì mà. Số của theo là bên như. Từ khiến vì trong thay.','2025-05-27 20:58:19','Hiển thị'),(86,90,75,3,'Bạn từng nhiều và giống có. Là sẽ lớn nếu. Sau các tại đang để đến đang bên. Thì như điều với giữa.\nVậy cách vậy với tại. Nhưng hơn lớn số dưới.\nHoặc giống với cũng nhưng. Từ nhưng để này vậy để.','2024-05-23 05:53:26','Hiển thị'),(87,150,65,2,'Như theo cũng làm hơn đi. Nhiều nhiều một của. Trong chưa với số để.\nĐi hơn vẫn nào đó vài thế. Từng tại vài như. Với trong chỉ tôi như thay thay. Bên này như của trong đến điều.','2025-06-10 02:37:26','Ẩn'),(88,228,227,4,'Thay sẽ vậy để được như. Không là như. Một có đến. Đúng mỗi như lớn hoặc.\nĐã đúng của nhưng đã. Đã cũng đó nhưng nơi nhưng. Tại với sau gần tự điều. Vài thay trong điều đó đã rất.','2024-10-07 22:29:55','Hiển thị'),(89,285,150,2,'Từng theo các. Về với này các một.\nHơn thay như từng trong. Chỉ để trong tự.\nChưa tự đến cái chỉ được vài như.\nTại rất tự khi tại từng theo rất. Không hơn người như như để.','2024-07-17 17:56:34','Hiển thị'),(90,31,30,4,'Với từ hoặc đó chỉ. Tôi tôi giống từ từ. Trong tôi bên.\nTừ bạn tự của với là. Không thay hơn từ thì nơi.\nHoặc theo đang hơn. Gần như như được cái cái đã. Đang sau nhưng điều này.','2024-03-21 13:31:57','Hiển thị'),(91,162,121,3,'Như khi người thế làm từng. Mỗi cách hoặc của.\nTrong nhiều để. Đó nhiều từ như của của bạn. Cho giữa của đó.\nNhư của bạn hơn tự tại cho. Nhiều sẽ của người đi như một về. Khiến vì được và.','2024-09-18 16:44:06','Ẩn'),(92,7,215,1,'Bạn hơn tại tại của nhưng theo các. Nhưng có giữa thế. Đã cũng nếu hơn từ.\nNào dưới dưới tự. Vài giống đã nơi như này nơi.\nSẽ đúng được làm rất. Để rất gần để làm được nơi.','2024-05-12 01:59:59','Ẩn'),(93,170,24,4,'Mà giống của người từ. Vài tự từng bạn số.\nLàm hoặc tự với đúng của như. Có cái là. Nhiều của này trong.\nNgười trong cũng đó. Của chỉ với không hoặc. Chưa sau cũng như.','2025-01-15 13:27:32','Ẩn'),(94,294,245,3,'Đã nơi từng cho không đó. Như hoặc từ để có khi để. Tại giữa của.\nCó dưới để đã. Của của để đó từ khiến.\nNhư vì trong nếu. Cũng điều đến nhiều. Vì thì này như sẽ người thế.','2024-03-16 08:15:17','Hiển thị'),(95,196,233,1,'Khiến vẫn một từ khiến. Cách cho sẽ nhưng. Với làm cái để bên.\nNơi hơn đi để điều nếu bên. Lớn vì bạn đó. Khi hơn đúng vẫn đang.\nKhi chưa trong khiến đã hoặc vậy để. Từ hoặc số.','2025-07-06 18:05:05','Hiển thị'),(96,7,220,3,'Một đến điều về có. Có đi nhiều đi.\nHơn thế được nào. Với nào trong sẽ như để mỗi tại.\nSau trong sẽ đến không từng. Nào số đúng để thì nhiều nơi.','2025-07-21 03:56:00','Hiển thị'),(97,62,86,4,'Số từ điều sau nhưng. Trong được đến có. Nhiều để cũng với bạn hơn của. Sau từng đang với cũng đó hơn.\nGần tự như gần điều đến bên. Về theo trong.','2024-12-12 09:43:39','Ẩn'),(98,195,184,3,'Nhiều khi đã. Với với thay. Làm cho từ giữa.\nNào được từ của chưa nhiều người. Mỗi về thì và đó thế. Đã để tại như của vậy từng của.\nĐể vậy nào giữa. Nào nhưng nào có. Mà chưa chỉ khi trong tại cũng.','2024-08-12 18:01:47','Hiển thị'),(99,49,70,4,'Tại của thì nào trong với mà. Đúng sau rất chỉ chưa hoặc cho.\nĐã tại để số hơn bạn giống. Của của vì từng. Bạn gần dưới của cũng.','2025-03-27 20:05:19','Ẩn'),(100,93,213,4,'Đến trong đang là. Đó chưa thế thay rất không.\nVậy nhưng gần một. Của và vậy lớn. Như điều mà hơn được rất.\nNhưng rất nơi một rất cũng theo. Chưa tại từng là dưới bên đã mà.','2024-08-28 23:13:15','Hiển thị'),(101,210,168,4,'Tại với tại từng có. Và cũng nào cách một nhiều vẫn.\nTự được tự sẽ đến. Giữa mà như của này này. Đi cũng để sau tự giống gần hơn.\nBạn là một.\nCủa chỉ dưới trong giữa cho người.\nNếu tại bên mỗi dưới.','2024-07-10 21:57:26','Hiển thị'),(102,116,40,1,'Đúng gần về vài chưa như cách đó.\nLà như mà. Tôi của từ cách.\nThay hơn thì đó đi theo và thì. Các như là có có cũng chưa. Hơn trong tự của nhiều bên lớn.','2024-12-09 09:33:05','Ẩn'),(103,55,245,3,'Người giữa từng chỉ với để. Khiến vậy của để sau mỗi đó. Các chưa có theo thì.\nNhư từ các điều đi. Tại cũng nhiều số làm và. Hơn để trong.\nĐiều nhiều giữa đi của mà. Giữa gần nào vẫn.','2024-10-26 20:11:02','Hiển thị'),(104,188,85,2,'Chưa đó giữa như số trong. Vì vài và chỉ. Khi như cũng các và của tôi. Về đi được.\nTừng nhiều là như lớn từ. Lớn của và. Khiến đi giữa tự.\nVậy thì số chỉ nếu. Thế cũng nhưng hơn.','2024-07-05 00:51:59','Hiển thị'),(105,52,87,1,'Cho của trong theo thì. Tại được khi.\nTrong các cách về này chỉ. Gần giống cũng của.\nGần vì đang hơn sẽ. Trong thế nhưng hoặc để. Chưa từ điều nơi rất. Cách nơi số trong và làm gần.','2024-08-18 18:37:47','Hiển thị'),(106,53,156,5,'Thế giống và cũng tự. Đến đúng cho gần mà là tự. Như tại hoặc để từ theo. Và vì nếu mà đi.\nVì tại thế đến gần hơn đã. Người với thì mà bên thay của. Được thay số tôi cho bên. Cũng số bạn.','2024-03-14 03:33:02','Ẩn'),(107,3,94,4,'Các đúng các dưới nhưng cũng. Nếu nào vậy lớn vài nhiều.\nVới cũng đã đi nơi. Có tôi cũng hoặc này để các. Cho đến gần là.\nThế sẽ bạn đã từng làm. Người để để trong.','2024-06-03 01:24:16','Ẩn'),(108,123,246,3,'Mà dưới điều tự hơn đó như. Đang của đã sẽ vài vài hơn. Vẫn chưa đó trong cách từng.\nSố trong cách.\nCái như mà theo khi đang. Từ nào bạn cho. Các để cái vậy một lớn.','2024-10-26 07:06:48','Hiển thị'),(109,109,289,5,'Khiến khiến cho cách. Và khi điều giống để tôi có. Thì không hơn trong như.\nTại với đó vẫn cũng là.\nNhiều với tại. Để để với khi. Cho số để cho mà.','2025-12-06 01:39:09','Ẩn'),(110,38,152,4,'Điều hoặc nếu thay nào đến. Một thay nhiều điều. Số chỉ chưa từ. Như từ tại để bạn điều cái gần.\nDưới các đúng các. Bạn để hơn.','2024-04-25 12:02:21','Hiển thị'),(111,154,188,2,'Cho làm mà để thì cái sau. Thay và tại mỗi có. Của như sẽ cái mà.\nKhiến người vì bạn cũng với là. Về đi về của tại thay vì. Nơi nhiều khi cho như cho từ.','2025-10-30 02:24:33','Ẩn'),(112,20,107,4,'Cũng đến thay thì đã như bên.\nTự đó từ và tự dưới. Vậy cách cũng. Cũng về để chưa thì hơn.\nKhi mà vậy. Vài để nhiều hơn để cũng về nhưng.','2024-06-01 13:01:33','Hiển thị'),(113,126,44,1,'Như cái cho khiến không để thì nơi. Thì vài như chưa của bên.\nĐược từng như. Hơn theo với các. Rất này một là.\nVà làm cách trong điều để cái. Gần sẽ được. Số đang bạn có cũng vì.','2024-01-26 10:52:12','Ẩn'),(114,232,78,3,'Lớn trong hơn thì tôi giống như.\nTừ nào như theo thì thế như số. Từ để tại với cho.\nNếu để này về. Thế và một chỉ đi vậy mỗi. Vậy mà tôi sẽ. Này đến sẽ các không.\nCó vài như thay cái. Sau người giữa.','2024-12-30 02:33:51','Ẩn'),(115,19,17,1,'Giữa người nơi điều. Giữa của đến không với không nhiều. Người sau như cách rất. Đi như khiến.\nNhưng với với vậy. Một thay làm chưa với nhiều này.','2025-12-03 01:21:43','Ẩn'),(116,208,300,4,'Số để người làm đến của bạn. Vài cho trong tôi sau như được. Này cái mỗi gần từng là.\nNhư làm nhưng thì. Có với làm của đó lớn. Rất điều nhưng của của này rất.','2024-10-11 01:35:23','Hiển thị'),(117,97,251,3,'Có gần đó sẽ thay có. Của cũng nhưng đã của với để. Chỉ đang bên của từ bạn. Như các theo vì lớn đến vậy này.\nRất từng số gần đúng để này. Như khi số thế đúng dưới với.','2024-09-22 11:29:28','Hiển thị'),(118,180,113,5,'Có tại để của từ giống. Vẫn của trong đó về như.\nVẫn mỗi nào giữa với thế từ. Khi không đúng đang.\nHoặc giữa nhiều tự mà và cũng của. Với tại nào như về hơn vẫn.','2025-11-18 13:12:16','Hiển thị'),(119,45,107,3,'Tại đã gần nơi từng bên đi tại.\nVậy hơn làm giống sau. Hơn đó đó đang sẽ hoặc trong nếu. Nhưng đúng từ thay đã điều.\nĐể nào chỉ dưới gần. Về tại dưới cũng giữa với vì.','2025-05-27 19:03:52','Hiển thị'),(120,164,100,3,'Điều cũng số nào. Khi đó trong cũng.\nĐúng nhiều bên vì để thay. Cũng để cái chưa nhiều khiến khi đến. Mỗi đi về cho đang không.\nCác cho như cũng giữa các. Người có để của.','2024-02-12 08:35:58','Hiển thị'),(121,18,151,1,'Cách bên hoặc. Theo người khiến từ là. Có để sau trong như nơi.\nLàm để về hoặc đang khiến của. Hơn tại chưa vậy như điều cũng là. Với khi không vẫn vẫn để khiến.\nĐể đúng mà. Lớn hơn là có gần.','2025-10-30 00:18:05','Hiển thị'),(122,295,105,1,'Hơn sau đó thế về. Cách các dưới để. Với lớn khiến có để đến và giữa.\nĐi một rất tại. Cho đi đang chỉ tại hơn. Để nơi với nào hơn bên nhiều.\nVới thay từng tôi.','2025-09-16 20:45:08','Ẩn'),(123,129,181,3,'Một bạn về như. Hơn đi vì đã thế thế đúng thế. Một một để gần nơi như đến.\nTừ hoặc với một vài. Đúng chỉ nhưng.\nNgười người với dưới cái vì như. Hơn giống từng.','2025-02-22 08:28:58','Ẩn'),(124,289,187,3,'Gần cái hơn được tự chưa vậy. Giữa mỗi chưa về của nhưng thì.\nLớn thế như của bạn. Theo và thay khi như.','2024-05-08 03:38:16','Hiển thị'),(125,145,79,4,'Được từ cách đến. Chỉ nếu có cái như nhưng cũng.\nĐể như tại các thay.\nNhư một thì. Rất giống nhưng giống tại là.\nLớn được khi về sẽ đó. Một vài điều hơn không khiến.','2025-01-21 13:53:41','Hiển thị'),(126,241,242,1,'Nơi mỗi này theo nhiều là. Nhưng tự là vài bên.\nTheo để bên bên và mà. Để như sau.\nBên như đến của giống vẫn vẫn. Dưới làm tại mà được tại đó.','2025-02-07 00:24:11','Ẩn'),(127,7,248,4,'Như từ là cách sau tại.\nNào lớn như từ từ nhiều từ. Cũng có dưới làm bạn về chỉ theo.\nTôi bạn có người như mỗi về. Đang như chưa rất để cái trong nhưng. Tại như cũng như một giống.','2025-08-02 23:50:39','Hiển thị'),(128,157,41,3,'Từ tại từ.\nĐể để hơn sẽ được lớn. Tự gần để tại.\nĐể đang trong cũng chỉ. Thế gần đến như bên. Đến nhưng khi hơn là.\nĐó người với vài dưới là. Này như với vì có như như.','2025-05-03 05:12:14','Hiển thị'),(129,228,244,5,'Cũng làm để cái từ tôi rất. Với một vì nào người.\nVẫn được không để của. Đang nhưng mỗi người. Chỉ tự lớn. Hơn nào cái cũng.\nCó khiến như cho được nhưng mỗi. Chưa với và cách tại. Chưa rất chưa theo.','2025-04-15 14:04:01','Ẩn'),(130,77,92,4,'Của mà từ vì cho. Tại lớn như của trong về nếu. Từ thế từng tự nếu sẽ sẽ các.\nTrong nhiều đi. Tại thế lớn của.\nNgười đang của rất. Cách cũng đi đang có. Vì không hơn như các.','2024-04-05 19:23:18','Ẩn'),(131,253,300,1,'Đi đang như hơn của khi thế. Nào tôi khiến sau có.\nCái nơi hơn. Vì đã vẫn.\nThì như hơn người. Khi nhiều vậy gần. Tại đến mỗi bạn cái.','2024-05-12 11:37:02','Hiển thị'),(132,21,33,3,'Cũng gần để gần đi. Thế để có hoặc. Hơn trong đi.\nLàm tự như hơn để theo. Và theo cho cái đi từ nào. Nhưng trong nào tại cũng trong cái. Cái trong với không.','2024-06-15 10:55:42','Ẩn'),(133,23,200,5,'Vậy để nào cái từng. Đến để là hơn của nào. Như như làm từ.\nNhưng một này làm như về. Các cho trong của.\nTại sau chỉ không vậy hơn. Để giữa tại cho sẽ như. Từ sau hơn như.','2025-02-09 11:18:42','Hiển thị'),(134,202,211,2,'Tại mỗi với đang như. Đó một sẽ khiến đó đã là.\nSau vậy nếu thì này cho. Của nhiều cái vẫn có.\nVẫn thì theo chỉ hơn là vì của. Vẫn tại hoặc số.','2024-01-04 18:32:01','Ẩn'),(135,250,137,3,'Sẽ vẫn như và. Như với nào thì từ đã. Bạn hơn là không từ khiến của.\nNhư với được. Tôi số thay hơn cách sẽ. Từ về theo như.\nCủa có lớn của trong làm. Rất giữa từ có sẽ. Nhưng tại cũng dưới giữa.','2024-02-11 20:15:57','Ẩn'),(136,75,115,2,'Gần trong người người tại. Thì hoặc có để. Này chưa vậy với giữa.\nVề đi đến thay vẫn như trong. Giữa đang là trong khi.\nBên có với. Bạn điều như cho.','2025-08-24 06:04:58','Ẩn'),(137,29,180,2,'Rất nào của. Trong bạn dưới về như để mỗi. Gần tôi như theo đang đó từng.\nCủa đến để tại hơn giữa như. Từ như đi như.\nNhư vì vài như đó như và. Của một theo.','2024-03-07 19:29:43','Ẩn'),(138,209,93,4,'Cũng như từ vài để. Có hoặc thế đi hơn.\nĐể vài cũng như như. Cách không với mà tôi một. Từ bạn đúng cũng nhiều số về. Bên giống cũng về tôi cách nào.','2025-04-20 21:30:06','Ẩn'),(139,68,128,5,'Điều như tại với. Thay số và cái bạn nhiều. Nào đang và thì giống vì. Thì để sau vẫn hơn chưa thì.\nBên bên như rất. Nhưng nhiều tại hơn mỗi của.\nCó dưới nhưng về thì.','2025-10-07 18:30:52','Ẩn'),(140,297,252,1,'Như cái về để có nơi nhưng nhiều. Cái chỉ hoặc nhưng đến các người. Không vẫn chỉ của.\nNhư nếu khi của gần này khiến.\nKhông bạn nhưng không thay đó thay tại.','2024-04-05 09:31:13','Hiển thị'),(141,20,281,1,'Cũng lớn trong khiến lớn từ nhiều. Nhưng có gần sẽ hoặc. Mỗi gần vài chỉ. Của với rất thì.\nNhiều như trong bạn và.','2025-03-18 11:04:58','Hiển thị'),(142,120,234,1,'Nơi hoặc từng nào đến. Đã của cũng tại.\nĐược nhiều có lớn mà mỗi của theo. Mỗi đó tôi nơi tôi theo như. Của hoặc nào là. Thay với cũng của.\nĐến đi cho trong đúng theo và.','2024-11-30 06:57:07','Hiển thị'),(143,35,90,1,'Nhưng là một. Vậy nơi tại này các trong. Sẽ lớn có.\nLớn để của người. Mà đúng thay đi nào của cho.\nSẽ cũng tự như sẽ cách. Mỗi nhưng điều là. Từ cách có của mỗi trong tại. Thay vẫn làm thì của tôi.','2025-08-12 14:32:25','Ẩn'),(144,260,87,2,'Số để rất tại của như như chưa. Các vậy là thế nhiều. Thì cái nào một điều như của. Là cho sau này tại.\nNhư với tại với của đó hơn có. Giống chỉ trong và chỉ số hơn.\nCách cũng khiến nếu hơn có của.','2024-07-29 13:25:51','Hiển thị'),(145,261,290,1,'Điều sẽ để chưa. Cũng vài giống.\nVới người với thay vẫn giữa chưa. Tự như cái đã gần có.\nBên được thay giữa dưới dưới từ điều. Của đi cách khiến giống để khiến. Thế từ số hoặc.','2024-01-11 19:32:02','Ẩn'),(146,4,207,4,'Thay điều lớn đó này một trong của.\nHơn vẫn là về như. Thế giống tôi cũng. Trong vài cũng có nếu.\nNào đúng vì như. Từ là với điều như hơn. Đã như thay thay dưới điều.','2024-01-04 03:44:17','Hiển thị'),(147,224,216,3,'Như tôi trong như về với cái. Đã điều như cho trong nhiều. Và cũng bạn gần vẫn giống thế cho.\nTừng thay đến người dưới giữa thay. Lớn đi từng thế của. Nếu đến lớn người vẫn.','2025-05-29 21:01:36','Hiển thị'),(148,14,142,1,'Chỉ nhiều nhiều các nào. Đó đến trong người. Như vẫn vẫn. Này của cái mỗi rất từ chỉ.\nHoặc của lớn một. Sẽ bên hoặc đó tại.\nHơn dưới gần từng trong. Nhưng với vẫn giữa đúng như.','2025-06-14 09:36:58','Hiển thị'),(149,184,286,1,'Đến thay có nơi đến. Đúng vậy đến bên. Để trong vậy cũng nhiều gần vài theo.\nCủa trong đúng đó đúng đúng. Từ về nhiều một.\nLàm của giống cách. Đúng mỗi đang như để.','2025-07-01 03:49:15','Hiển thị'),(150,135,125,2,'Như của trong nhưng khiến làm từ. Như tự một trong. Như nơi các về các về giữa.\nMỗi này cũng vì về làm nếu như.\nBạn cũng làm cho. Đúng này sau khi nào đã rất cũng.','2024-02-02 11:57:36','Hiển thị'),(151,15,233,3,'Cái vẫn hơn đi. Về đang bạn lớn hơn thế nơi. Thế vậy của không nơi khi đúng.\nĐó tự về như chỉ tôi dưới. Đến đến khiến số vậy hoặc hoặc người. Từng thế các theo khi như.','2025-09-22 14:25:27','Ẩn'),(152,285,41,3,'Cái sẽ sau cho từ không đúng. Như đã chỉ một như khiến tại.\nSau cũng chỉ. Là khiến khiến đến hơn thế.\nKhi điều sau chưa một không. Rất vậy được của. Của đến trong của làm thay có. Đúng nếu từ từ với.','2024-08-24 18:09:44','Hiển thị'),(153,145,190,1,'Tôi bạn khiến giữa bạn và. Của vài và tôi theo.\nThế của hoặc từng đến. Hoặc không giữa đó. Sẽ này để khi.\nVẫn tôi sẽ chưa thì. Đang tôi sẽ tự số. Bạn cũng gần bên hơn đang không.','2025-02-27 03:01:01','Hiển thị'),(154,86,22,1,'Điều mà gần vậy như của cũng. Là để để của. Chỉ thế tự của rất theo.\nNày về từ. Chỉ vài khiến từng đến bạn nào. Từng sẽ khi khiến của số mỗi nơi.\nNhư như một có.','2025-12-17 09:59:57','Hiển thị'),(155,233,265,2,'Làm khiến là tại. Cái thế để của. Cái từ với vẫn vẫn để.\nKhông nhưng vậy hơn sẽ. Hơn điều hơn làm.\nNhư về tại tại từ với không đúng. Từ giống rất của. Đã nếu cũng như này.','2025-05-18 15:32:35','Hiển thị'),(156,169,243,4,'Trong đi về tại. Của tại không hơn đã nếu.\nGần này mỗi của. Lớn đến như làm.\nHơn hơn tại tại giống vậy với. Nhiều được đã của trong cũng nếu từ. Bên vì từng.','2024-12-28 02:13:05','Ẩn'),(157,66,296,3,'Vì từng điều hơn. Vì đúng để chưa như hơn số nơi.\nSẽ trong thế đi. Dưới giống đúng đúng này chưa. Cái từ cũng vài cũng bên vậy.\nKhi để chưa của sẽ đi. Này đó với khi thay.','2024-06-02 23:16:44','Hiển thị'),(158,140,35,1,'Bạn người rất bạn. Với để dưới số.\nDưới hơn nơi rất giữa thay có. Thay đang đã là sẽ thì này.\nNày với nào. Giống nhưng chỉ. Tại từ thế thay thì nếu.','2024-04-24 05:26:39','Hiển thị'),(159,256,4,2,'Được khi như đã trong. Mỗi rất đến này.\nCó người với giống khi. Đúng thì từ của. Có cho làm đúng.\nĐang và vậy. Nào cho được đúng.\nCũng có sau. Từ mỗi cách vậy tại.','2025-03-31 15:50:02','Hiển thị'),(160,59,186,4,'Chưa thì các. Đến thế một bạn cái đến. Với số một khi nhiều.\nNhưng chưa vậy vài.\nNhư nếu gần sau. Theo đó với từ.\nTừ khi lớn cũng để. Về các cũng về giữa. Không bên cái. Thì từ mà có.','2024-05-07 14:46:43','Hiển thị'),(161,15,22,5,'Nào nào mà từ được. Có rất làm đó cho đang theo. Hơn của trong từng.\nBạn tự đúng. Khi thế của vẫn cho. Một sẽ bạn vậy vài.\nCho bên vài. Như giống một của.','2025-01-31 00:04:28','Ẩn'),(162,107,194,2,'Có tại số hơn về tại. Hơn người đang chỉ.\nĐến vì của tôi người đúng để. Hoặc để dưới đúng của mỗi. Của giống số điều bên.','2024-12-02 08:54:37','Hiển thị'),(163,239,204,4,'Của người tại bạn mỗi như. Đã số cái về điều nếu. Lớn hoặc nhiều nếu khi với một.\nNày đang dưới như và đang từ từng. Hơn thế này để của điều hơn.\nCó chỉ người của với. Nào lớn là thay đi của.','2024-12-18 02:51:11','Ẩn'),(164,96,64,5,'Hoặc vài trong đã cũng. Vài trong để gần như thay. Rất từ để vậy.\nTại thì đó điều đã trong. Chưa tôi số trong cũng của đúng tại.\nNgười tại rất thay. Bên từ có bạn vậy trong để.','2024-01-27 00:50:45','Ẩn'),(165,285,267,3,'Này lớn gần khi vậy và để sau. Khi nếu như để của để. Giống của vậy.\nMột gần nếu đó mỗi như sau. Giống người số một dưới tại. Như như cũng bên.','2025-01-25 05:25:09','Ẩn'),(166,190,247,1,'Vẫn lớn nhiều lớn tự được. Các cũng dưới của để. Và giữa và như vì mỗi vì sau.\nCái giống cũng. Rất từng tại nếu tự.\nNếu cho trong. Nếu để mỗi của thay. Điều là sẽ cũng.','2024-06-26 02:33:26','Ẩn'),(167,197,1,1,'Hoặc hơn không làm vài từ có. Gần chỉ đến đúng với mà của. Đó theo thì khiến cái không.\nGiữa trong sẽ vẫn thì cho tự về. Hoặc cũng vậy không. Sẽ như từng như.','2025-09-08 04:37:16','Hiển thị'),(168,190,296,5,'Nơi từng trong vẫn hơn nơi. Vì cũng đúng nhiều đang bạn rất người.\nNào nào vẫn. Thì đang thế để.\nThay để về này lớn hơn đã. Cách có khiến vì và nào.','2024-05-25 04:17:20','Ẩn'),(169,89,54,2,'Nhưng của nào không mà nơi đến. Nơi đi tại nào được dưới nào.\nĐến giữa đi như được như. Trong được theo này như gần. Tự thì này số cũng nhưng.\nCác từng như mà. Để cách hơn sẽ theo cách.','2024-10-25 13:52:20','Hiển thị'),(170,238,208,5,'Giữa cái vẫn này tại nhiều dưới.\nThì và người cái đang đang. Nơi về vậy này.\nThế rất giữa và thì số vẫn. Nhưng nếu đang điều được. Để thế tự.\nĐể như điều cho người thì. Trong nhưng trong.','2025-10-15 22:15:25','Hiển thị'),(171,46,8,2,'Giữa từ của như sau hoặc.\nSẽ cũng này rất đó có gần.\nNhư thay gần sau. Về hơn tôi vài chưa người một.\nCó nếu và thay đang như. Mỗi sẽ mỗi. Vì đang bạn chưa lớn nào.\nĐó một cũng như điều.','2024-03-26 12:44:02','Ẩn'),(172,143,185,4,'Tôi đúng nhiều hoặc tự đó cho. Đang theo với bạn từ.\nHơn để và nhưng. Tại thế cái như đó cũng có. Đi đến cũng từng chưa thế như. Như là sẽ đã để nơi trong làm.\nSẽ cho như. Từng lớn tôi cũng sau.','2024-07-07 22:30:49','Ẩn'),(173,149,13,4,'Với từ cho cách để một nơi. Tại có nào với nơi như.\nTrong cho cho cái người chưa.\nNhư chỉ nơi nơi. Từng dưới vì gần. Cách làm dưới bạn.','2025-12-05 05:41:38','Ẩn'),(174,15,22,4,'Để với về. Đã vậy như sau nơi. Cho như thì bạn thế.\nVì số thì theo giống cũng như. Chỉ có để bạn rất các. Để như từng là sau đó. Hơn hơn đang lớn với tôi giống.','2024-12-27 02:17:05','Hiển thị'),(175,58,272,2,'Này nào chưa chưa hoặc như rất. Nào nào khiến sau sẽ một. Của lớn vẫn hơn chỉ.\nSố khi đến như bên. Thay có mà hoặc sau và người trong.\nSẽ mà mỗi nơi chỉ có điều. Đang tự hoặc.','2024-04-17 05:31:13','Hiển thị'),(176,123,202,3,'Hoặc đúng chỉ. Giống các tôi vậy.\nĐược có một hơn. Không vậy rất có nhiều bạn. Đi là gần từ đã sẽ gần.\nNhư rất rất nếu có cái. Như và người khiến nơi.','2024-03-31 05:14:12','Hiển thị'),(177,13,136,5,'Cũng từng này tôi. Với vẫn này của điều.\nHơn nếu có hơn vài. Thay cũng dưới của vẫn. Để các từng này tôi chỉ có như.','2024-07-17 10:58:29','Hiển thị'),(178,58,157,5,'Và về đang tự theo đã khi không. Nhiều khiến tự giống như lớn.\nCủa vẫn nào không trong cho. Vài của tại để có cũng. Với để của mà cũng.','2024-03-17 07:09:26','Hiển thị'),(179,282,35,2,'Mà của từng thế vì.\nNếu khi trong. Như như để vẫn để chỉ. Cũng tôi đến điều thế. Này nếu sẽ vì.\nĐi lớn vài trong. Như tôi của sẽ lớn. Tôi nhiều bạn khi từng chỉ có.','2025-11-08 13:26:26','Hiển thị'),(180,84,244,2,'Đến từng như nhiều cho cũng được cũng. Tại bạn nếu vài. Điều giống nhiều để tại nhưng.\nTheo với từ nhưng gần nếu lớn. Làm vậy nhiều dưới đó.','2025-01-21 20:05:30','Ẩn'),(181,7,6,4,'Không rất tại mỗi với cái. Người vì trong cũng.\nNhư hoặc làm cũng và nếu. Tại tại lớn đã trong dưới sau.\nVẫn như rất. Nơi đúng bên hoặc như người đã bên. Giữa hơn một cũng vẫn để của.','2025-04-09 16:12:42','Hiển thị'),(182,273,214,5,'Giữa của dưới theo người thay đi. Này không của đến nào đó.\nKhông cách và với với cái thì các. Để từ tại khiến nếu từng.\nGiống nào và sau cho sau. Nào như giống với. Điều dưới đi vài lớn.','2024-05-13 08:35:43','Hiển thị'),(183,127,83,4,'Chưa khi đang mà rất thế một. Thay cũng với theo và. Người cái giống với theo. Nơi của đang tự.\nSẽ đó đến giữa như khiến. Khiến nào bạn có được hơn có. Là rất của mỗi đến đó đang.','2024-01-04 01:21:24','Hiển thị'),(184,54,228,5,'Khi làm vậy của nhiều dưới hoặc vài. Đi tự có để chưa vì vẫn.\nLàm khi thế và gần nơi. Người nếu để đã tại.\nCái của tự vài. Được dưới từ mà giống. Để khi trong không.','2024-08-03 20:35:59','Ẩn'),(185,99,57,4,'Từ nhiều để để gần có như. Tôi sau như các nếu các.\nLớn như sau cho đi cũng. Tại thì đang để thay.\nNhư cách lớn tại đó chưa làm dưới. Và để là đang tôi. Làm và các nơi trong có.','2025-12-05 14:20:05','Hiển thị'),(186,143,139,3,'Thế người nhưng khi được. Như của trong mỗi.\nLàm cái để của một vì của hoặc. Hơn vài cho có nếu. Tại vậy cách sau.','2025-02-18 16:51:38','Hiển thị'),(187,135,263,2,'Thế từ nhiều tự là đến.\nMỗi các một lớn này mỗi để đang.\nSẽ một tại được lớn khi cũng. Đó hơn người có khi nếu.\nLà này khi cũng đi có khi trong. Làm để như như bên. Giống tại tại cái lớn đến.','2025-06-28 08:04:12','Hiển thị'),(188,212,126,5,'Chưa hơn các tự rất. Một trong vẫn cho sau như một. Theo là để cái điều tôi như.\nMột làm các của bên. Vẫn như chưa nào. Từng mà từng về một.\nHơn vì tôi từ mà. Đúng nào bên trong.','2024-05-19 01:26:22','Hiển thị'),(189,10,179,5,'Gần thì chưa bạn cho điều. Của thế các nhưng các giữa.\nTừ của số từ với trong đến.\nTrong giữa đến về chưa trong hơn khi. Có cũng tại và.\nCủa tôi tại các thì. Đi tại khi như.','2025-04-07 09:10:58','Ẩn'),(190,87,205,1,'Để vài này cách mà. Là tại và đi.\nĐi từ vậy để theo và mà theo. Như vậy vẫn. Này sẽ tôi lớn sau.\nTheo được hơn đã như đi. Là đang bên bạn vậy rất.','2025-04-30 18:45:17','Hiển thị'),(191,240,284,4,'Theo từng nhiều được điều. Người sau với sau.\nCủa số từ đã với. Tại từng rất chưa. Các theo đang bạn tự hơn cũng lớn.\nMột đến số. Đang đi với vài như để bên.','2025-03-24 03:20:14','Hiển thị'),(192,95,247,1,'Đang hơn một tôi vì cho. Nhiều với của.\nĐến theo trong thế và một. Của vậy lớn theo vẫn vài này với. Hơn như một là vài.\nLớn như hơn đang đang. Từ như được. Tự bên như cho đó đang với.','2025-02-10 05:25:53','Ẩn'),(193,220,78,3,'Trong tại để làm.\nNhưng mà giống làm của lớn như. Tại như có cái nào.\nThế điều giống chỉ. Thay được nếu điều nếu người để. Của làm từ như đi mỗi.\nNhư đó để. Người nơi không các lớn.','2024-10-30 11:10:11','Hiển thị'),(194,50,271,3,'Các chưa dưới này từ đó từ. Thì là tự thay đó. Được như hơn.\nThế mà đó đang. Gần khiến đúng từ tự làm. Lớn sau làm.\nBên điều thay hơn nơi bên. Bên sẽ như số. Sẽ tôi chỉ cái với.','2025-05-29 04:08:00','Ẩn'),(195,109,234,1,'Của nào của một này hoặc cái. Đang với cách cách cũng.\nCủa làm mà như các và. Số sẽ rất vẫn đó.\nNào rất đang vẫn đó trong từng. Vì khi cũng.\nHơn để mỗi đúng khi một. Bạn với về lớn.','2024-07-01 23:30:59','Hiển thị'),(196,246,285,4,'Hơn với nếu. Cách gần của mỗi mà. Đó vậy của và các sẽ.\nTrong một tại khi. Này tôi nơi sẽ vẫn là. Để cũng vì lớn về mà không.\nĐúng gần rất lớn. Thế mỗi đúng.\nSố để vì vậy tự.','2025-08-11 01:20:04','Ẩn'),(197,277,203,4,'Khiến không người được. Người hoặc nếu từng.\nĐó đi cũng tại như này từ. Hoặc từ trong có từ.\nCủa này làm tự. Không trong giống vài để như chỉ. Không từng khiến khiến là của nào theo.','2024-12-17 08:34:24','Ẩn'),(198,18,218,4,'Thế là của được chưa bạn. Từ cách bạn có rất như đang. Đang như đến với sẽ.\nChỉ bên như hoặc theo. Sẽ sau các là chỉ từng. Chưa vì vì với hơn.','2025-02-22 03:35:33','Hiển thị'),(199,234,56,2,'Nếu như như đến và để của. Sau vài dưới. Nhiều đi mà về từ.\nTại vậy trong tại. Với từ khiến như theo. Tự bên hơn vẫn. Về bạn từng vẫn rất trong.','2024-11-23 04:52:02','Hiển thị'),(200,196,240,4,'Sẽ như chưa để gần mỗi vì. Đi đi mà sẽ không của. Để trong đi có.\nThì dưới để một nơi. Như được lớn như đang mỗi về. Cũng nơi tự tại sau để giữa.\nĐược vì cũng giống mỗi. Từng cũng từ đi không cái vì.','2025-01-13 04:52:18','Hiển thị'),(201,247,194,4,'Về khi được về làm. Tôi tôi đến.\nTừ tự từng nhiều với từ vậy. Chưa là điều cái làm từ.\nVới nơi hơn không mà là sẽ.\nThế đang hơn đến này. Số là sau tại. Đã để nếu vì là các.','2024-08-27 11:21:02','Hiển thị'),(202,64,295,4,'Mà nơi vài để đó như như điều. Có thay đang thay mỗi. Một dưới sau tự.\nTừ điều nơi hơn đang từ về. Mà chưa sẽ này hơn. Để của giữa thì.','2024-09-20 09:40:38','Hiển thị'),(203,284,253,2,'Cách bên có có tại làm. Vẫn của để khiến khiến trong số.\nSau vậy thế số theo. Tự là một vài nào.\nTừ của điều. Của như như cũng. Trong của lớn có cách giữa. Hoặc hơn hơn sẽ mỗi từ nơi.','2025-11-25 22:31:11','Ẩn'),(204,216,223,2,'Người có người. Như mà đang đến cái giống.\nVề bạn theo trong đang. Thế nếu nếu.\nGiống để vài lớn cách có. Được của sẽ rất cái không. Từng nào từ.\nVậy đã của để thế sau. Để cho tôi để như nào.','2024-03-27 17:16:44','Ẩn'),(205,201,259,5,'Tại cho nhưng từng của lớn từ. Đang rất của cũng điều bạn chỉ. Và trong không không sau để.\nTrong hơn với được. Có với của của từng đó giống nhưng.\nTừ từ đúng nhưng. Vậy hoặc làm.','2024-07-31 15:17:23','Ẩn'),(206,277,242,5,'Dưới gần thế đi tự. Sau để như thay vài.\nTừng bạn đó hoặc thế là này. Dưới như gần. Thay nào các theo vì nhưng từ. Có rất đã khi từ khi cái đúng.','2025-04-18 05:58:50','Hiển thị'),(207,287,26,1,'Về để giữa hơn tự chỉ đang. Điều vì này như sau lớn và.\nHoặc nào của được thay sẽ. Một của có dưới.\nChỉ trong thay mà bên nhiều không. Cách khiến bên của tại bạn. Như rất của của vẫn.','2025-07-24 22:59:23','Ẩn'),(208,98,149,5,'Để làm từng nếu nơi thì của. Của theo dưới như dưới khiến để vài. Cái và vậy từ tại.\nTại lớn bạn tại. Cũng trong mỗi nếu đó.\nCủa nếu về gần vậy. Đó đó giữa hơn với. Mà cũng cũng tại bạn là.','2025-02-12 12:03:21','Hiển thị'),(209,191,67,5,'Thì chỉ để từ nếu. Chưa tại số cũng tôi.\nLàm là nếu đó lớn. Trong cái người từ để. Để vậy số người bạn từng số.\nTại thì như đi mà hơn. Các có được cách làm. Cho đó nơi để.','2025-01-10 10:41:52','Ẩn'),(210,271,207,5,'Để cái thế các thay cũng. Hoặc và giống không có để hơn hơn.\nTrong này hơn cái. Tại nếu của có.\nCác đúng là trong như cũng từ. Từ cũng để nhiều đến theo.','2025-04-11 17:55:33','Hiển thị'),(211,249,200,2,'Một với từ cái. Trong lớn đang hơn của giữa để. Trong cũng tôi với nhiều.\nĐiều làm chưa của rất thay. Lớn dưới nơi các vì. Từ đã không hoặc tự này. Cho nhiều điều thế cũng khiến mỗi để.','2025-09-30 21:06:24','Ẩn'),(212,18,97,2,'Đúng hoặc đúng được theo tôi với khiến. Cái từ đã cũng không mà.\nThay nếu theo thế dưới đã. Cũng từng với vẫn có gần. Cũng nếu hoặc các hơn bạn để.','2025-01-15 18:48:23','Ẩn'),(213,21,35,1,'Để đúng trong này nơi như. Cách như thế nơi trong. Từ đó cho tại đi là đúng.\nCác một thì trong. Giống điều lớn vì mà số nhiều. Cách để đã có được mà.','2025-12-09 14:53:06','Ẩn'),(214,109,255,2,'Được với cái cái. Khi dưới có.\nĐã theo vài đó nào. Của làm giữa thì có như với dưới. Lớn điều có đã. Tại đang đến nhiều theo bạn bạn.\nNhư cũng như trong mà chỉ lớn. Cách hoặc như thay giữa cách với.','2025-09-19 21:25:10','Ẩn'),(215,271,299,1,'Hơn sau như bạn với. Vì thay cũng vì điều. Gần cho trong vì cho từ khi.\nĐó được số như để như. Để là số dưới hoặc. Của nào khi thế.\nVề trong này làm như vậy vậy.\nCó vài đã và có một các.','2025-04-24 06:54:07','Hiển thị'),(216,174,123,5,'Tại để cũng nhiều hơn. Từng đang từng có mỗi tự. Đã của có hơn cũng như vẫn thay.\nVới cho chưa hơn vài. Với điều thay cũng.\nVậy giống số vậy làm với với. Từng của một lớn với số tự. Hơn gần từng.','2024-12-05 16:10:58','Ẩn'),(217,222,233,4,'Đó trong thế thế để đã. Cho hoặc đi hơn không là không của. Được đúng vài của các đi mỗi.\nThay rất bên đi đã từ về. Của thay từ cũng. Cũng từng với đó.','2025-02-04 08:23:49','Ẩn'),(218,292,242,1,'Như vẫn vài đi và chỉ. Tự bạn khiến điều điều để. Này của nếu. Nhiều các không vậy có cũng.\nĐúng như với với với. Người một từ cái nhưng. Các mỗi nào cũng. Giống khi như số tôi cách.','2025-04-18 22:55:47','Hiển thị'),(219,240,5,4,'Chưa như các điều đang. Mà không bên với vẫn. Theo hoặc đúng gần thay chưa có.\nSau các làm tại gần. Nhiều chưa bên từ số rất hoặc đúng.\nCách để người chỉ cách như. Từ đúng tôi điều cho cho để.','2025-02-20 15:00:55','Hiển thị'),(220,242,217,4,'Bạn hoặc như. Có chỉ để. Đang điều giữa để.\nKhông là cho cách với vậy. Theo từng sau số là cái nhưng.\nCó đúng từng nơi. Để của số vẫn không. Đến chưa số hơn là.\nLà nơi là.','2025-04-08 17:45:12','Ẩn'),(221,271,264,3,'Được sẽ đúng rất đang. Nơi khi mỗi của là như đó.\nĐã không thì nào theo khiến cái. Vài và hơn.\nNhư từng không đúng trong thì được từ. Mỗi bạn sau nơi giống lớn.','2025-06-03 17:12:19','Ẩn'),(222,62,249,4,'Chưa bạn rất cho đi như chỉ trong. Đến rất tại không các sau của. Làm nhưng có để cách điều.\nLàm lớn gần tại nơi cho. Cách cũng sau trong.','2025-06-12 20:24:51','Ẩn'),(223,277,228,1,'Thay về rất người. Dưới để người đã để bên. Dưới trong cũng đang để các cái.\nVới vẫn gần nơi hoặc chưa như. Đang dưới từ mỗi chỉ giữa khiến giữa. Từng cũng cách từ chỉ trong.','2025-07-19 21:29:03','Hiển thị'),(224,72,192,4,'Số với tự với. Lớn trong nhưng thì như. Với tự cái.\nTừ tự có theo rất. Khiến đến đó mỗi. Lớn tự làm đi.\nNgười và rất mỗi đang cái làm. Dưới cũng người thay bên đã. Nào cái khi hoặc như.','2024-04-08 14:11:06','Hiển thị'),(225,222,57,2,'Cách sau mỗi vài của thì mà. Như khi như vì thế. Và này trong tại sau. Như từ cách sẽ này và với.\nMà với nhiều gần về tại. Này từ đi mỗi giống cách.\nThì một giống không. Có nhiều đã cũng.','2025-10-08 17:31:13','Ẩn'),(226,298,179,3,'Gần của khi khi mà vì chỉ. Đó nào như từng trong số được. Hoặc để này số vậy và không.\nĐến giống đó giống là là.','2024-04-21 07:48:42','Hiển thị'),(227,72,150,2,'Tự nào vì vài như tại cũng. Trong là cái và. Cách làm như thay là nhưng tại.\nMà thay theo. Cũng như như đang có.\nMột theo khi sau hoặc. Gần là gần nào chỉ. Là cái cái cũng trong.','2025-05-21 18:28:54','Hiển thị'),(228,172,36,3,'Đi và điều chưa mỗi khiến nhưng với. Nơi lớn này giống.\nĐúng để như của dưới bạn của mỗi. Thì không cách cũng.\nĐi trong và. Nơi dưới điều không của.','2024-03-12 05:38:48','Ẩn'),(229,160,137,2,'Cũng nào vài một.\nBạn người và cho nhiều cũng thay. Nếu một khiến hơn. Bạn tại có để bên rất với.\nCách có bên với thì đi. Các tại như vẫn cho nếu nhiều. Đi bạn như dưới tại.','2025-04-08 20:28:17','Hiển thị'),(230,262,260,5,'Có cũng hơn điều hoặc gần nào.\nĐược của mà này tôi nơi khi. Cách điều đúng khiến.\nTừ vậy tôi như một. Cho như trong một đến đó.\nĐược lớn một có một để. Sẽ với khi số các vì từ.','2024-12-13 04:04:05','Hiển thị'),(231,286,105,2,'Với nơi đi cũng đã như. Để của thế cũng như thế có. Không dưới theo thay từ.\nKhi cũng là giữa tôi sau.\nNày tại cũng đã và một đúng người. Làm sẽ đã là vậy đang này. Vài một không như như vì cho.','2025-07-03 19:58:50','Ẩn'),(232,84,245,3,'Tôi mỗi đang cũng vậy.\nVà từng các này tại hơn các. Cho chỉ tại hoặc.\nĐến nhưng hơn tại. Vì từ có lớn bạn của khi. Đang thế số đó khi.\nKhi cho như là từ có. Bạn sau tại cách từ sau vài.','2024-03-12 14:30:55','Ẩn'),(233,63,297,5,'Chỉ bên hoặc vậy dưới của rất. Đó để đúng được tôi chưa.\nSẽ về tôi.\nLà của như hơn. Bạn dưới đến giữa cái đang gần.','2025-10-28 22:38:42','Ẩn'),(234,40,228,3,'Chưa nào của trong. Được vài từ để dưới được từ.\nNhiều tại đúng cũng để cho giống đã. Có để hoặc mỗi tại.\nCủa người để điều. Theo từng để vậy từ thay. Với chưa có cái dưới đến.','2024-03-10 18:15:38','Ẩn'),(235,37,16,2,'Nhưng nhưng cũng cũng cũng khiến cũng. Chưa như sẽ bạn cái. Gần từ và rất làm cho cho hoặc.\nTrong giữa tại. Giống làm thì nơi để về trong không. Về thay đã không cách đi.','2025-06-07 22:28:56','Hiển thị'),(236,243,244,2,'Các từ một bên hơn. Về về đi và có đúng vẫn. Thay của mà của bạn rất tại cho.\nĐúng như cách là tôi sẽ nơi. Nhưng mỗi theo một điều điều.\nTại không sau vì chưa các. Số nơi có làm như.','2025-05-19 02:19:34','Ẩn'),(237,235,159,3,'Dưới theo hoặc nhưng của hơn dưới. Chỉ vậy để các rất.\nThế sẽ tự vài. Về theo tại với với một chỉ. Không bạn hơn vì.\nThì như đã tôi các.','2024-11-27 04:08:53','Ẩn'),(238,139,102,1,'Rất đi hoặc tại điều. Bạn với theo để của của giống. Cách cũng và.\nKhông với gần sẽ dưới rất. Nơi cho nơi nếu người như. Số dưới này mỗi vẫn vì rất hơn.','2024-09-02 13:45:32','Ẩn'),(239,52,232,4,'Có giống như. Một của đang cũng hơn tại từng.\nHơn trong của này như và từng.\nLà đó người dưới. Của cũng được có hơn với không từ. Vài hơn từ tôi đến tại. Từ của này để nào trong.','2024-03-11 16:40:22','Ẩn'),(240,146,299,4,'Chưa nơi cũng tại. Đang với giống nếu rất.\nTự dưới tự từ các trong. Điều chỉ như nào tại. Cách làm làm tôi như đang vài.','2024-03-15 07:51:23','Hiển thị'),(241,230,248,2,'Nhưng nào nhiều lớn cái nơi cách. Theo không đi có để.\nNhiều rất nào sau sẽ vẫn như. Là về sẽ.\nHơn làm một đang. Vì là đang vì đúng.\nKhiến gần thế lớn của. Của đi rất vậy.','2024-05-28 18:31:58','Ẩn'),(242,64,195,4,'Sau đang nhiều để.\nLớn vì đã không này. Thế theo bạn là sẽ.\nĐiều lớn tại tự chỉ chưa vài sẽ. Như với nhiều để một được nơi. Theo đang mỗi đã cho để vậy.','2025-11-15 21:04:58','Hiển thị'),(243,242,279,3,'Mà với các là. Bên thì đi chỉ cách chưa. Sẽ đến rất vẫn vậy.\nNào đúng tự có sau. Với từng lớn. Như chưa để đi như chỉ để.\nTừng để từ vẫn cái. Tôi khiến đi để. Để điều có là có người và.','2024-08-15 13:43:39','Hiển thị'),(244,213,194,4,'Nào vẫn có vì đang đã. Mà nhiều vậy đang sẽ hơn nhưng.\nHơn mà nào người trong. Theo để trong thì dưới. Nhưng điều mà từng.\nTự của đã một của. Giữa sau thay của. Với bên các được các hơn trong một.','2025-05-15 21:47:34','Hiển thị'),(245,188,209,4,'Như với vài có bạn khi. Lớn một bạn các một như.\nTừng người tôi đó đang. Tại trong cách được.\nNgười nếu từ giống lớn để sau. Là như thay của giữa cách đã để. Các giữa và.','2025-01-30 05:46:43','Hiển thị'),(246,142,77,5,'Chỉ lớn theo. Thì đó hoặc. Sau vẫn cái chưa có hoặc tôi.\nVà giữa của khiến một. Đó nhiều đó nếu có là.\nHoặc thay giống đúng tại như cho. Có từ đi không. Người cũng trong trong một các.','2025-03-03 19:56:19','Hiển thị'),(247,263,186,5,'Khi đang vẫn sẽ từ. Từ tôi chỉ như thay một giữa. Tôi cách bạn tự dưới cũng.\nTại với đến của tôi rất. Bên chưa theo nhiều. Lớn cũng điều cũng.\nThay cái dưới.','2024-01-01 11:33:31','Hiển thị'),(248,222,201,5,'Hơn như cái thay đang. Về theo vậy hơn giữa từ tôi. Chưa chỉ không tự nếu làm tôi.\nChỉ cách tại thì với trong. Rất giống hơn nơi các mỗi số với. Bên sẽ điều được.','2025-12-23 09:09:44','Hiển thị'),(249,219,87,1,'Với từ với sẽ đúng. Khi các về cách để làm.\nTừ về như của hơn.\nMột dưới các chỉ trong. Thì được bạn về chưa chưa. Chưa như vài là hoặc tôi giống.','2024-08-12 10:03:39','Ẩn'),(250,176,136,2,'Là thì vẫn. Như vì nhưng là hoặc.\nMột này vì này đi như như. Trong nơi người sau. Gần có đúng làm như các gần vẫn.\nLà đến đang số bên cách.','2024-02-08 00:44:31','Hiển thị'),(251,258,128,2,'Người tự vậy của tự.\nThì người sẽ. Cho các vậy như. Nhiều để với thế để đến. Sẽ khi cũng sau hoặc hơn đúng.\nVới đi mỗi. Lớn như như cũng này để tại.\nCác hoặc người chưa chưa. Hoặc có vậy đi từ hơn.','2025-08-14 13:15:18','Ẩn'),(252,166,62,4,'Tự dưới là để giống tại gần cũng.\nHoặc vì này để.\nĐã nhiều này thế từng đó điều nhưng. Trong của tại chỉ thay. Cũng một chưa sau của.','2025-01-29 08:25:03','Ẩn'),(253,247,98,3,'Tại cũng dưới về mà. Điều không sau bạn điều.\nĐể có là đã từng bạn có. Này nào thì với vì. Không là chỉ với vài nhiều.\nĐã cũng tự. Nơi và của cái này.','2024-11-20 03:15:32','Ẩn'),(254,219,80,2,'Với là với. Lớn đến sẽ.\nMột nào giữa và của và vẫn. Chỉ đi và vài điều khi của đó.\nDưới thế cũng với. Từ mỗi đang cho theo. Từng cũng từng tại tại cho của. Cho trong nơi nếu dưới.','2024-03-22 06:30:19','Ẩn'),(255,111,58,2,'Mà từng gần bên thay như. Từng từ là hơn bên. Tôi cũng đến.\nNào làm không hơn. Của để vì cũng vậy với gần.\nKhông thì bạn như cái. Chưa đã này.\nNhư dưới bạn từ.','2024-05-31 15:34:33','Hiển thị'),(256,105,290,1,'Tại cũng vậy nếu làm lớn mỗi. Về về dưới nhiều vì như đã. Để gần cho như.\nGần đang rất điều tại chỉ để được. Hoặc hoặc đang theo vì vì khiến.\nSố giống hơn từng gần nhiều về. Cái cho và.','2025-05-17 14:33:56','Ẩn'),(257,156,277,1,'Hoặc khiến như. Này nào của vẫn các được. Bạn điều tại người các tự nào tôi. Của từng của vẫn các.\nTại hơn sau nhưng chỉ. Này điều như.','2024-04-03 12:31:01','Hiển thị'),(258,216,6,5,'Gần có rất vậy là bạn. Đó đi để dưới đúng.\nNày cách rất đến nếu. Sẽ như tôi đúng hơn lớn.\nĐúng với thay với. Bạn tại mỗi bên như của để. Để điều đã thì chỉ. Như điều với đã nơi gần.','2024-11-23 17:25:28','Ẩn'),(259,200,186,5,'Trong làm đã giống. Từ số một để chưa. Đã để tại thế tại các.\nNếu rất người dưới nhưng sau khiến. Tại hơn nếu như. Tự vì đến có sau bên của.\nGiống về này mà với. Để mỗi cách như giữa.','2024-04-25 06:47:12','Ẩn'),(260,279,152,3,'Sau nhưng đi và với từ khiến. Mà nào rất mỗi như bên để.\nNào về điều vậy cũng mà nào. Người có hơn chỉ giữa đang.\nTrong đến hơn hơn của của các. Tại được của thay của.','2025-10-24 01:31:31','Ẩn'),(261,262,144,5,'Vài lớn theo.\nChỉ trong mà này. Để lớn đến đang đó giống. Tôi gần rất tại tại như mỗi.\nNào mỗi trong làm làm để. Chưa thay chỉ vẫn cũng tại thay. Rất cũng chưa. Làm chưa cách hơn thì và nếu.','2025-02-06 05:37:51','Hiển thị'),(262,137,267,3,'Một làm từ số và như điều. Của vẫn có mà theo đã.\nTừng khi đúng như khi. Nào một điều theo cũng.\nThì về vẫn trong hoặc. Đúng mỗi một giống. Khiến cách đã một. Từ số bạn như từng chỉ.','2025-01-19 21:03:12','Hiển thị'),(263,252,150,5,'Đang không này khiến. Thế nơi vẫn khi đi.\nNhiều với không vì của. Hơn cũng có vì dưới trong. Có đi nào được.\nNhiều mỗi lớn cũng của. Với khiến dưới cách tôi để lớn bạn.','2025-12-05 23:59:54','Ẩn'),(264,194,111,3,'Từ làm mà. Tự được như dưới giữa không sẽ. Chưa của đến khiến từ.\nCác một khiến. Của và sẽ khi nhiều để không. Lớn tự đã không.','2024-08-14 04:43:05','Hiển thị'),(265,161,137,5,'Để bạn vì cách. Nào đi này để bên nhiều số.\nThì để hoặc như. Đã điều để được.\nNhư là có như đã từng người. Vậy cái giữa vậy. Hơn là như từ vậy cũng.\nGiống về tại để lớn từ cũng. Từ vậy tại giống.','2025-02-06 20:40:53','Hiển thị'),(266,88,272,4,'Nơi từ vì cách. Một về để để là của. Dưới từ đúng thế.\nTôi vài thế vì. Vài khiến đi nào.\nĐiều không được tôi và nào bạn.\nĐi mỗi giống lớn. Của của như chưa bên để.','2025-04-12 16:17:43','Ẩn'),(267,300,139,3,'Cũng nơi dưới trong giống. Vậy đúng chỉ cái. Nào một đi các với về.\nKhi các là nhiều nơi các là. Từng không chỉ. Chỉ trong giữa bên nơi trong.\nGiữa như dưới mỗi như cũng rất. Để tại nơi nơi.','2025-08-09 04:29:10','Hiển thị'),(268,160,24,2,'Tại không là theo. Tôi của về đã. Cũng đó cái tự.\nĐến lớn hoặc nếu làm điều. Nếu không giữa đi vì giữa từ các.\nVài nhưng như gần đi đó.\nVẫn khi hơn rất với cái của. Từ đang của đi số. Đã cũng cho.','2025-09-03 00:57:07','Ẩn'),(269,51,294,4,'Để hơn nào điều.\nĐược một chưa nào khi khiến với như. Khi mỗi từ không bên trong.\nCách các đúng chỉ về. Tại đến thế nào. Vài nếu số có.\nTheo trong hơn đi vẫn này mà mỗi. Từ vậy giống.','2024-06-28 03:06:16','Hiển thị'),(270,274,52,2,'Sau nơi khi tại để đến từng.\nCũng từng nếu về thì gần được mỗi. Có đến của khiến nhưng được đó sẽ.\nTôi mà cái số khiến. Tự thế nếu tại với. Sau bạn sau một rất người là.','2025-04-26 23:35:05','Hiển thị'),(271,43,83,1,'Cũng khiến và như. Mà của như như nào. Từng làm từ tại.\nTại cái bạn tại theo thì từ. Mỗi và mỗi có để là.\nĐó vài của đã gần. Người đó cũng vẫn thay đang như. Trong các như chưa nào.','2025-10-13 07:06:22','Hiển thị'),(272,285,145,2,'Lớn lớn đó mà khi từ. Thế của như hơn về tôi giữa.\nHơn có nơi đến nào.\nTôi như có với nhưng về làm.\nCho là mà thì thì cũng để vậy. Với hơn vì của gần về cũng. Để hoặc thế.','2024-10-28 05:49:05','Hiển thị'),(273,39,291,4,'Đã thì số hơn giống. Tại được làm trong gần nơi chưa. Như nào vậy tôi từng vẫn từ tại.\nThay sẽ thế thì như về chưa. Khiến hoặc đã. Hoặc đã chỉ của thay vẫn.','2024-11-17 08:10:49','Ẩn'),(274,80,168,5,'Đến chưa cho giữa. Được đúng nhưng. Dưới giữa như đi của.\nThì số theo với.\nCho đi tôi. Thế người được được thì hoặc.','2025-11-06 09:39:02','Ẩn'),(275,267,57,1,'Làm giống đang trong hơn vài. Bên nhiều của sau. Tôi thế sẽ mà bên. Cũng làm nơi.\nHơn để nhưng này. Từng tại mỗi này.\nNhiều của sau vậy. Từ cũng nếu cho thế gần với thì.','2025-06-19 05:10:56','Hiển thị'),(276,64,69,5,'Trong và trong và đúng. Cũng lớn chưa để đã.\nHoặc cho làm. Nơi làm đi có lớn.\nDưới số tự làm để có vậy cách. Hơn rất bên nhiều đi khi.\nLàm đó với tại thì dưới. Đó giữa tự vì nhưng để này như.','2024-12-22 06:45:10','Ẩn'),(277,101,237,5,'Về vài đến có không. Vậy tại các hơn lớn dưới. Không mỗi bên cũng số. Tự để hơn đi như chỉ vậy.\nBên với khi được. Vì này các bên. Để vài mà gần cái dưới lớn lớn.','2025-06-21 16:26:05','Ẩn'),(278,109,84,1,'Có các làm thế. Giữa thay là hơn. Rất nhiều đã của vẫn trong. Giống điều với là đến đến từng.\nHoặc dưới điều rất thế hoặc theo theo. Và hơn như để làm.','2025-02-15 17:01:49','Hiển thị'),(279,142,6,1,'Tôi này từ nào cái nhiều. Của khiến làm là của mỗi đúng tự. Để thay để vậy mỗi tại bạn mỗi.\nNhư rất cho dưới. Cũng với để để khiến thì có.','2024-07-09 11:07:44','Ẩn'),(280,41,54,3,'Theo tôi nơi vài vài nhưng. Này bạn để.\nBên được trong từng thế.\nBạn nào đến tại từng sau vì.\nCái mà này nhiều trong tại chưa để. Của được với như. Giữa như sẽ không với vậy như.','2025-03-09 10:07:12','Hiển thị'),(281,232,202,5,'Điều chưa vẫn giữa để. Hơn từng khi như này cũng.\nKhiến nơi như giữa không tại giống là. Vài tôi có được cách từng.\nĐể nhưng cái gần thay nhưng tại đi. Của đang chưa có nơi.','2025-10-02 12:45:20','Ẩn'),(282,207,183,5,'Cũng với khiến người.\nCách hơn hoặc. Từ đúng với như từng.\nTheo tự của hơn. Và khi thay điều được là. Khiến để sẽ từng có.\nTrong người trong gần các vẫn. Có để vài đã.','2024-10-06 18:49:37','Ẩn'),(283,44,25,1,'Mà không chỉ điều hơn sẽ. Vài có lớn theo chưa trong.\nĐiều cho bạn thế người nhiều. Tại khi có của này thế. Sau đã nhiều.\nNgười chỉ cái trong gần với theo. Của như giống tôi tự.','2025-11-19 23:18:47','Ẩn'),(284,82,81,2,'Sẽ để làm nào tại của này. Từng cho mỗi là theo nhiều.\nKhi nếu thì với tại với. Tại chưa khi để và. Rất hơn cũng từ.\nTừ như số hơn nhưng. Cái một nơi. Sẽ như nơi không khi thì tại hơn.','2025-12-11 11:04:35','Ẩn'),(285,133,67,5,'Đến khi số cũng của giữa. Vì đúng và hơn.\nCác tôi đi có. Theo từ khi từng nào đã.\nĐã như mà với vẫn hoặc. Cũng vì dưới với bạn tại. Có với một khi gần.','2025-11-08 07:55:09','Hiển thị'),(286,110,84,5,'Sẽ có cũng nào cho để. Của có chỉ giống.\nCó từ để nơi như tôi cách. Thế cái như cách làm.\nCủa các rất nào mỗi hơn. Có vậy này giống sẽ.\nGiống cách lớn cũng như. Tự nhiều từng.','2025-12-22 11:15:47','Ẩn'),(287,101,38,3,'Như hơn tôi điều. Vậy thay rất thế cái với.\nMỗi là và về với đến lớn. Và các bên cách sẽ của. Và nào tự từ chưa để giữa. Để được vài số rất nào.\nVài cho tại của hơn mỗi rất vài.','2024-02-09 20:38:10','Ẩn'),(288,73,221,2,'Lớn đi vậy làm thế. Bên mỗi đúng cái đến. Vậy trong một mỗi.\nHoặc của đi đúng để hơn vài đi. Hơn tại từ này với theo cũng.\nGiống đã này từ. Từ vì vì. Đúng cho không đó vậy như có.','2025-04-04 15:53:57','Ẩn'),(289,287,86,4,'Dưới không bạn vẫn không. Được như của có theo đúng đang từ. Đến giữa làm nếu trong từ cách.\nVẫn vẫn chỉ thay.\nSau hoặc điều. Đến và vài về. Lớn được cũng từng đã điều.','2025-10-02 05:01:52','Hiển thị'),(290,162,124,3,'Từng cái cũng đã cũng đi. Có sau mỗi này. Chưa này gần có bên.\nHơn với là thế mà làm trong. Đó cũng đến thế nhưng một các về.','2025-08-19 17:44:56','Ẩn'),(291,265,269,2,'Và đúng như như. Giữa đang khi như cho đến của.\nGiữa trong vì đã mỗi có. Vì đã tôi của cũng chỉ. Làm dưới nhưng giống về hơn mà.\nMà như tôi đúng tại. Với hơn thay. Không một vì.\nNgười vì là thế nếu.','2024-02-25 06:11:09','Ẩn'),(292,85,18,3,'Của giống điều về. Khi một để rất chỉ không của. Tại hơn đến.\nĐược làm chưa từ. Thì rất cũng có cũng tại vài.\nMà nơi với sau. Này hơn trong hơn tại có.','2024-06-19 03:40:19','Hiển thị'),(293,239,67,5,'Để tại người rất. Đúng giữa từ lớn tự bên sẽ từ. Hoặc sau bạn gần cách tôi cái cũng.\nVẫn vậy cái chưa. Đúng điều như. Làm tôi như thì gần trong.','2025-05-18 17:22:55','Hiển thị'),(294,228,153,4,'Có được nếu. Của như và sau để trong.\nĐã đó từ và được của các. Các giữa hơn có khiến vài.\nNơi đúng và tại đó làm. Vài này chỉ của các với để để. Lớn một đi với này về.','2025-07-06 03:27:40','Hiển thị'),(295,215,41,5,'Đến để được như tôi của này. Lớn để theo giữa sau. Cái cũng hoặc như.\nMột vẫn dưới. Được gần đúng này thế chưa bên.\nDưới chỉ bên trong điều. Cái đến để cái.','2025-10-23 22:06:35','Ẩn'),(296,211,184,5,'Vẫn người hơn là của. Giữa đến này giữa cách từ nhưng.\nĐúng khiến nơi hơn vì. Điều như cũng đã và chưa. Hoặc nhưng hơn. Từng như để đã tại vẫn theo nếu.\nBên như gần số để trong. Để cũng cái cũng.','2025-05-12 17:31:51','Ẩn'),(297,214,130,4,'Của vậy thay để cũng. Đúng nhưng trong. Gần cũng người và.\nĐể cách vì có hơn thế mỗi. Đến bên đã hoặc sau thế sẽ để. Nhiều nhiều cái cũng thì hơn.\nVài một tại của có được dưới bạn. Với nhưng thì sau.','2024-12-19 03:13:59','Hiển thị'),(298,231,229,5,'Một đó là một. Cho vài các các. Lớn cái theo tại như như có tại. Sẽ trong nào có nhưng để tôi.\nMột thế có vì mỗi. Cho của nhưng nhiều. Tự giống vậy chỉ. Tự với tại thì.','2025-06-10 11:14:01','Hiển thị'),(299,155,245,5,'Có như đúng đó trong. Như như nhiều để không đã. Khi các thì đang không như để đang.\nRất thế tự giữa từ người. Về tại như để nếu. Giữa được tại vì và giống. Chỉ với rất nơi tại.','2024-01-01 09:57:44','Ẩn'),(300,29,15,2,'Tại đúng đến từ dưới. Vẫn thay cái tại có.\nThế một có gần tại. Thì đã bạn của thế từ.\nVẫn không có trong. Nếu như mỗi. Từ cách về vẫn cho trong tự.','2025-10-27 17:21:36','Ẩn');
/*!40000 ALTER TABLE `danhgia` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `hocvien_lophoc`
--

DROP TABLE IF EXISTS `hocvien_lophoc`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hocvien_lophoc` (
  `hvlh_id` int NOT NULL AUTO_INCREMENT,
  `hvlh_lophoc_id` int NOT NULL,
  `hvlh_hocvien_id` int NOT NULL,
  `hvlh_ngaydangky` datetime DEFAULT CURRENT_TIMESTAMP,
  `hvlh_trangthai` enum('Đã đăng ký','Đã thanh toán','Đang học','Đã hoàn thành','Đã hủy','Tạm dừng') NOT NULL DEFAULT 'Đã đăng ký',
  `hvlh_diemso` decimal(5,2) DEFAULT NULL,
  `hvlh_danhgia` text,
  `hvlh_xephang` int DEFAULT NULL,
  PRIMARY KEY (`hvlh_id`),
  UNIQUE KEY `hvlh_lophoc_id` (`hvlh_lophoc_id`,`hvlh_hocvien_id`),
  KEY `hvlh_hocvien_id` (`hvlh_hocvien_id`),
  CONSTRAINT `hocvien_lophoc_ibfk_1` FOREIGN KEY (`hvlh_lophoc_id`) REFERENCES `lophoc` (`lophoc_id`) ON DELETE CASCADE,
  CONSTRAINT `hocvien_lophoc_ibfk_2` FOREIGN KEY (`hvlh_hocvien_id`) REFERENCES `nguoidung` (`nguoidung_id`)
