CREATE TABLE `lophoc` (
  `lophoc_id` int NOT NULL AUTO_INCREMENT,
  `lophoc_khoahoc_id` int NOT NULL,
  `lophoc_ten` varchar(100) NOT NULL,
  `lophoc_mota` text,
  `lophoc_trangthai` enum('Chưa bắt đầu','Đang học','Đã kết thúc','Tạm dừng') NOT NULL DEFAULT 'Chưa bắt đầu',
  `lophoc_ngaybatdau` date NOT NULL,
  `lophoc_ngayketthuc` date NOT NULL,
  `lophoc_soluonghv` int NOT NULL DEFAULT '20',
  `lophoc_giaovien_id` int NOT NULL,
  `lophoc_phonghoc` varchar(50) DEFAULT NULL,
  `lophoc_lichhoc` text COMMENT 'JSON format: {"thu": [2,4,6], "gio": "19:00-20:30"}',
  `lophoc_tailieu` text COMMENT 'Danh sách tài liệu',
  `lophoc_created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `lophoc_updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`lophoc_id`),
  KEY `lophoc_khoahoc_id` (`lophoc_khoahoc_id`),
  KEY `lophoc_giaovien_id` (`lophoc_giaovien_id`),
  CONSTRAINT `lophoc_ibfk_1` FOREIGN KEY (`lophoc_khoahoc_id`) REFERENCES `khoahoc` (`khoahoc_id`) ON DELETE CASCADE,
  CONSTRAINT `lophoc_ibfk_2` FOREIGN KEY (`lophoc_giaovien_id`) REFERENCES `nguoidung` (`nguoidung_id`)
) ENGINE=InnoDB AUTO_INCREMENT=326 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

