DROP TABLE IF EXISTS `nguoidung`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `nguoidung` (
  `nguoidung_id` int NOT NULL AUTO_INCREMENT,
  `nguoidung_email` varchar(100) NOT NULL,
  `nguoidung_matkhau` varchar(255) NOT NULL,
  `nguoidung_hoten` varchar(100) NOT NULL,
  `nguoidung_sdt` varchar(15) DEFAULT NULL,
  `nguoidung_diachi` text,
  `nguoidung_avatar` varchar(255) DEFAULT NULL,
  `nguoidung_vaitro` enum('Học viên','Giáo viên','Quản trị viên') NOT NULL DEFAULT 'Học viên',
  `nguoidung_trangthai` enum('Kích hoạt','Vô hiệu hóa','Chờ xác nhận') NOT NULL DEFAULT 'Chờ xác nhận',
  `nguoidung_sodu` decimal(12,2) DEFAULT '0.00',
  `nguoidung_nganhang` varchar(100) DEFAULT NULL,
  `nguoidung_stk` varchar(20) DEFAULT NULL,
  `nguoidung_created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `nguoidung_updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `nguoidung_trinhdo` enum('A1','A2','B1','B2','C1','C2') DEFAULT NULL COMMENT 'Trình độ tiếng Anh của người dùng',
  PRIMARY KEY (`nguoidung_id`),
  UNIQUE KEY `nguoidung_email` (`nguoidung_email`)
) ENGINE=InnoDB AUTO_INCREMENT=1054 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

