DROP TABLE IF EXISTS `thanhtoan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `thanhtoan` (
  `thanhtoan_id` int NOT NULL AUTO_INCREMENT,
  `thanhtoan_hocvien_id` int NOT NULL,
  `thanhtoan_lophoc_id` int NOT NULL,
  `thanhtoan_sotien` decimal(10,2) NOT NULL,
  `thanhtoan_phuongthuc` enum('Thẻ ngân hàng','Ví điện tử','Chuyển khoản') NOT NULL,
  `thanhtoan_trangthai` enum('Thành công','Thất bại','Đang xử lý','Đã hoàn tiền') NOT NULL DEFAULT 'Đang xử lý',
  `thanhtoan_ngay` datetime DEFAULT CURRENT_TIMESTAMP,
  `thanhtoan_magiaodich` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`thanhtoan_id`),
  KEY `thanhtoan_hocvien_id` (`thanhtoan_hocvien_id`),
  KEY `thanhtoan_lophoc_id` (`thanhtoan_lophoc_id`),
  CONSTRAINT `thanhtoan_ibfk_1` FOREIGN KEY (`thanhtoan_hocvien_id`) REFERENCES `nguoidung` (`nguoidung_id`),
  CONSTRAINT `thanhtoan_ibfk_2` FOREIGN KEY (`thanhtoan_lophoc_id`) REFERENCES `lophoc` (`lophoc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

